-- Target content/state snapshot. No sequences, sessions or timestamps generated by this query.
set sqlformat csv
select json_object(*) as history_row from greeting_history order by greeting_id;
select json_object(*) as hello_setting from hello_config order by config_id;
select json_object(*) as world_setting from world_config order by config_id;
select json_object(*) as hello_entry from hello_entries order by entry_id;
select json_object(*) as world_entry from world_entries order by entry_id;
select json_object(*) as component_row from lab_components order by component;
select json_object(*) as state_row from lab_state order by state_key;
select json_object(*) as migration_row from databasechangelog order by orderexecuted;
select json_object(name,type,line,text) as source_row from user_source order by name,type,line;
select json_object(application_id,version,availability_status) as application_row from apex_applications where application_id in (810004,810005) order by application_id;
select json_object(page_id,page_name,page_title) as page_row from apex_application_pages where application_id in (810004,810005) order by application_id,page_id;
